import * as THREE from 'three';
import { OBJExporter } from 'three/examples/jsm/exporters/OBJExporter.js';
import { createScene } from './data/object.js';
import fs from 'fs';
import path from 'path';

// Create the 3D object from the provided script
const object = createScene();

/**
 * Function to expand InstancedMeshes and collect all meshes into a single group 
 * where all world transformations are baked or preserved for export.
 */
function prepareForExport(obj) {
    const root = new THREE.Group();
    root.name = 'export_root';

    // Ensure all world matrices are up to date
    obj.updateMatrixWorld(true);

    obj.traverse((child) => {
        if (child.isMesh) {
            if (child.isInstancedMesh) {
                const instanceMatrix = new THREE.Matrix4();
                for (let i = 0; i < child.count; i++) {
                    child.getMatrixAt(i, instanceMatrix);

                    // Combine child's world matrix with the instance's local matrix
                    const worldInstanceMatrix = child.matrixWorld.clone().multiply(instanceMatrix);

                    const newMesh = new THREE.Mesh(child.geometry, child.material);
                    newMesh.name = `${child.name}_${i}`;

                    // Apply the combined matrix to the new mesh
                    newMesh.matrix.copy(worldInstanceMatrix);
                    newMesh.matrix.decompose(newMesh.position, newMesh.quaternion, newMesh.scale);
                    newMesh.updateMatrixWorld(true);

                    root.add(newMesh);
                }
            } else {
                const newMesh = new THREE.Mesh(child.geometry, child.material);
                newMesh.name = child.name;

                // Copy the world matrix to the new mesh's local matrix
                newMesh.matrix.copy(child.matrixWorld);
                newMesh.matrix.decompose(newMesh.position, newMesh.quaternion, newMesh.scale);
                newMesh.updateMatrixWorld(true);

                root.add(newMesh);
            }
        }
    });

    return root;
}

// Prepare the object for export (flattening hierarchy and expanding instances)
const exportReady = prepareForExport(object);

// Apply -90 degrees X-rotation to convert to Blender Z-up space as requested
exportReady.rotation.x = -Math.PI / 2;
// Important: update world matrices after rotation so exporter picks up the changes
exportReady.updateMatrixWorld(true);

// Initialize OBJExporter and parse the object
const exporter = new OBJExporter();
const result = exporter.parse(exportReady);

// Define output path and ensure directory exists
const outputPath = '/root/output/object.obj';
const outputDir = path.dirname(outputPath);
if (!fs.existsSync(outputDir)) {
    fs.mkdirSync(outputDir, { recursive: true });
}

// Write the result to the output file
fs.writeFileSync(outputPath, result);
console.log(`Successfully exported 3D object to ${outputPath}`);

